parameters.jsCode:
// Claude 응답 JSON 추출 → 당근 AI CMS 입력칸별 값으로 변환
const raw = $json?.content?.[0]?.text ?? $json?.content ?? $json?.text ?? '';
let text = typeof raw === 'string' ? raw : JSON.stringify(raw);
text = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const s = text.indexOf('{'), e = text.lastIndexOf('}');
if (s !== -1 && e !== -1) text = text.slice(s, e + 1);
let d;
try { d = JSON.parse(text); } catch (err) { d = { report_markdown: (typeof raw === 'string' ? raw : text), parse_error: err.message }; }
const j = (v) => Array.isArray(v) ? v.join(', ') : (v ?? '');
const f = $('고객사 정보 입력').item.json;
return [{ json: {
  생성시각: new Date().toISOString(),
  상호명: f['상호명'], 업종: f['업종/카테고리'], 지역: f['지역(시/구/동)'],
  말투톤: d.tone ?? '',
  핵심키워드: j(d.core_keywords),      // 고객사관리 '핵심 키워드'
  서브키워드: j(d.sub_keywords),        // 고객사관리 '추천 서브키워드'
  불포함키워드: j(d.excluded_keywords), // 자동캠페인 '불포함 키워드'
  필수기재상단: d.top_required ?? '',    // 자동캠페인 '필수기재내용 상단'
  필수기재하단: d.bottom_required ?? '', // 자동캠페인 '필수기재내용 하단'
  Primary: j(d.primary_keywords), Secondary: j(d.secondary_keywords),
  LongTail: j(d.longtail_keywords), Regional: j(d.regional_keywords),
  Additional: j(d.additional_keywords), 해시태그: j(d.hashtags),
  리포트: d.report_markdown ?? '', 파싱오류: d.parse_error ?? ''
}}];

